<?php
namespace App\Http\Controllers\Admin\Auth;
use App\Http\Controllers\Controller; use App\Models\User; use App\Services\AdminActivityService; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Hash;
class AdminLoginController extends Controller {public function login(Request $r,AdminActivityService $log){$v=$r->validate(['admin_login'=>'required|string|max:190','password'=>'required|string|max:255']);$u=User::where('role','admin')->where('is_active',true)->where(fn($q)=>$q->where('email',$v['admin_login'])->orWhere('admin_identifier',$v['admin_login']))->first();if(!$u||!Hash::check($v['password'],$u->password))return back()->withErrors(['admin_login'=>'Invalid Admin credentials.']);Auth::login($u);$r->session()->regenerate();$r->session()->put('admin_last_activity',now()->timestamp);$log->log('admin_login','user',$u->id);return redirect()->route('admin.dashboard');}public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/');}}
